(() => {
  const host = document.getElementById('fu-notifications');
  const maxVisible = 2;
  let language = 'en';

  // Game item, NPC and vendor names remain untouched.  These patterns cover
  // every notification generated by Follower Unbound's own batching, trade,
  // crafting and equipment systems.
  const localize = (message) => {
    let text = String(message || '');
    if (language !== 'tr') {
      const englishRules = [
        [/^Altın paylaşıldı: Takipçilerin her biri (.+) altın aldı\.$/,'Gold shared: each follower received $1 gold.'],
        [/^Madencilik\/Odun: Takipçilere (.+)x (.+) verildi\.$/,'Mining/woodcutting: shared $1x $2 with followers.'],
        [/^Takipçiler (.+)x (.+) topladı\.$/,'Followers collected $1x $2.'],
        [/^(.+) adlı takipçi (.+) eşyasını kuşandı ve korumaya aldı\.$/,'$1 equipped and protected $2.'],
        [/^(.+): Takipçilerin her biri (.+) altın aldı\.$/,'$1: each follower received $2 gold.'],
        [/^(.+) recovered: (.+)\.$/,'$1 recovered: $2.']
      ];
      for (const [pattern, replacement] of englishRules) { if (pattern.test(text)) return text.replace(pattern, replacement); }
      return text;
    }
    const rules = [
      [/^(.+) purchased (\d+)x (.+) from (.+)\. \(-(.+) Gold\)$/,'$1, $4 adlı satıcıdan $2x $3 satın aldı. (-$5 Altın)'],
      [/^(.+) sold (\d+)x (.+) to (.+)\. \(\+(.+) Gold\)$/,'$1, $4 adlı satıcıya $2x $3 sattı. (+$5 Altın)'],
      [/^(.+) sold (.+) to (.+)\. \(\+(.+) Gold\)$/,'$1, $3 adlı satıcıya $2 sattı. (+$4 Altın)'],
      [/^(.+) crafted a (.+)\.$/,'$1 bir $2 üretti.'],
      [/^(.+) crafted (.+)\.$/,'$1 $2 üretti.'],
      [/^(.+) drank a (.+) Potion! \((.+): (.+)\)$/,'$1, $2 iksiri içti! ($3: $4)'],
      [/^(.+) used a Cure Poison potion\.$/,'$1 Zehir Tedavi İksiri kullandı.'],
      [/^(.+) applied (.+) to their weapon!$/,'$1 silahına $2 zehri sürdü!'],
      [/^(.+) consumed (.+)\. \(Thirst: (.+)\)$/,'$1, $2 tüketti. (Susuzluk: $3)'],
      [/^(.+) consumed (.+)\. \(Hunger: (.+)\)$/,'$1, $2 tüketti. (Açlık: $3)'],
      [/^(.+) is thirsty, but has nothing to drink!$/,'$1 susamış ama içecek bir şeyi yok!'],
      [/^(.+) is hungry, but has nothing to eat!$/,'$1 aç ama yiyecek bir şeyi yok!'],
      [/^(.+) recovered: (.+)\.$/,'$1 geri aldı: $2.'],
      [/^(.+) looted: (.+)$/,'$1 yağmaladı: $2'],
      [/^Followers collected (.+)\.$/,'Takipçiler $1 topladı.'],
      [/^Party Loot: (.+)$/,'Grup Yağması: $1'],
      [/^(.+) bought and equipped (.+) for (.+) gold; it is now in their inventory\.$/,'$1, $2 eşyasını $3 altına satın aldı ve kuşandı; eşya artık envanterinde.'],
      [/^(.+) cannot afford (.+): needs (.+) gold, has (.+) spendable\.$/,'$1, $2 eşyasını alamaz: $3 altın gerekli, $4 harcanabilir altını var.'],
      [/^(.+): (.+) is no longer in stock\.$/,'$1: $2 artık stokta yok.'],
      [/^(.+): (.+) is no longer available\.$/,'$1: $2 artık mevcut değil.'],
      [/^(.+) finished trading: sold (.+) item\(s\), bought (.+) item\(s\)\.$/,'$1 ticareti bitirdi: $2 eşya sattı, $3 eşya aldı.'],
      [/^(.+) sold (\d+)x (.+) to (.+)\. \(\+(\d+) Gold\)$/,'$1, $4 adlı satıcıya $2x $3 sattı. (+$5 Altın)'],
      [/^(.+) purchased (\d+)x (.+) from (.+)\. \(-([\d,]+) Gold\)$/,'$1, $4 adlı satıcıdan $2x $3 satın aldı. (-$5 Altın)'],
      [/^(.+) purchased supplies from the merchant\.$/,'$1 tüccardan malzeme satın aldı.'],
      [/^(.+) sold (.+) item\(s\) to the merchant\.$/,'$1 tüccara $2 eşya sattı.'],
      [/^Companions ate a meal\.$/,'Takipçiler yemek yedi.'],[/^Companions had a drink\.$/,'Takipçiler içecek tüketti.'],
      [/^(.+) ate a meal\.$/,'$1 yemek yedi.'],[/^(.+) had a drink\.$/,'$1 içecek tüketti.'],
      [/^Ore mined & shared with companions\.$/,'Maden çıkarıldı ve takipçilerle paylaşıldı.'],[/^Firewood shared with companions\.$/,'Odun takipçilerle paylaşıldı.'],[/^Bonus gold shared with companions\.$/,'Bonus altın takipçilerle paylaşıldı.'],[/^Resources shared with companions\.$/,'Kaynaklar takipçilerle paylaşıldı.']
    ];
    for (const [pattern, replacement] of rules) { if (pattern.test(text)) return text.replace(pattern, replacement); }
    return text;
  };
  window.fuSetLanguage = (value) => { language = value === 'tr' ? 'tr' : 'en'; document.documentElement.lang = language; };

  const removeToast = (el) => {
    if (!el) return;
    try {
      if (el.parentNode) {
        el.parentNode.removeChild(el);
      } else if (typeof el.remove === 'function') {
        el.remove();
      }
    } catch (_) {}
  };

  const iconFor = (message) => {
    const text = String(message || '').toLocaleLowerCase();
    if (/looted|loot|yağma|yagmal/.test(text)) return ['icon-loot-hand.png', 'Loot'];
    if (/craft|üret|ureti|bolt|arrow|torch|meşale|mesale/.test(text)) {
      if (/potion|potions|iksir/.test(text)) return ['icon-potion.png', 'Crafting'];
      if (/torch|meşale|mesale/.test(text)) return ['icon-lantern.png', 'Crafting'];
      if (/arrow|bolt|(^|\s)ok(\s|\.|$)|oklar|civata/.test(text)) return ['icon-arrows.png', 'Crafting'];
      return ['icon-anvil.png', 'Crafting'];
    }
    if (/purchase|purchased|buy |bought|sold|sale|satın|satin|satıldı|satildi|merchant|vendor|stock/.test(text)) {
      if (/sold|sale|satıldı|satildi/.test(text)) return ['icon-sell.png', 'Trade'];
      return ['icon-coin.png', 'Trade'];
    }
    if (/poison|zehir/.test(text)) return ['icon-poison.png', 'Poison'];
    if (/potion|cure|iksir|healed|tedavi/.test(text)) return ['icon-potion.png', 'Potions'];
    if (/thirst|drink|içecek|icecek|susuz/.test(text)) return ['icon-water.png', 'Needs'];
    if (/hunger|food|\beat|yemek|hungry|(^|\s)a[çc](\s|$)/.test(text)) return ['icon-food.png', 'Needs'];
    if (/collect|harvest|flower|ingredient|çiçek|cicek|topla/.test(text)) return ['icon-leaf.png', 'Gathering'];
    if (/equip|equipped|kuşan|kusan|armor|weapon|protection|protected|koruma|kıyafet|kiyafet/.test(text)) {
      return ['icon-shield.png', 'Equipment'];
    }
    if (/recover/.test(text)) return ['icon-loot-hand.png', 'Recovery'];
    if (/gold|coin|para/.test(text)) return ['icon-coin.png', 'Gold'];
    return ['icon-info.png', 'Follower Unbound'];
  };

  window.fuClearNotifications = () => {
    try {
      if (host) host.innerHTML = '';
    } catch (_) {}
  };

  window.fuNotify = (message, locale) => {
    try {
      if (!host || typeof message !== 'string' || !message.trim()) return;
      language = locale === 'tr' ? 'tr' : 'en';

      const toast = document.createElement('div');
      toast.className = 'fu-toast';
      const [iconName, iconLabel] = iconFor(message);

      const icon = document.createElement('img');
      icon.className = 'fu-toast-icon';
      icon.src = `assets/icons/${iconName}`;
      icon.alt = '';
      icon.setAttribute('aria-hidden', 'true');
      icon.onerror = () => { icon.style.display = 'none'; };

      const text = document.createElement('div');
      text.className = 'fu-toast-text';
      text.textContent = localize(message);

      toast.title = iconLabel;
      toast.appendChild(icon);
      toast.appendChild(text);
      host.appendChild(toast);

      // Sınırı aşan en eski bildirimleri güvenle kaldır
      while (host.children.length > maxVisible) {
        removeToast(host.firstElementChild);
      }

      window.setTimeout(() => {
        try {
          if (!toast.parentNode) return;
          toast.classList.add('fu-leave');
          window.setTimeout(() => removeToast(toast), 280);
        } catch (_) {}
      }, 4200);
    } catch (e) {
      console.error('fuNotify error:', e);
    }
  };
})();
